draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // draw a book
  ctx.fillStyle = '#663300';
  ctx.fillRect(W/2-50, H/2-50, 100, 100);
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.strokeRect(W/2-50, H/2-50, 100, 100);

  // draw a stick figure reading the book
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2-150, H/2-100, 20, 0, 2*Math.PI);
  ctx.fill();
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(W/2-150, H/2-80);
  ctx.lineTo(W/2-150, H/2-40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2-150, H/2-60);
  ctx.lineTo(W/2-120, H/2-40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2-150, H/2-60);
  ctx.lineTo(W/2-180, H/2-40);
  ctx.stroke();

  // add a thought bubble with a lightbulb
  ctx.fillStyle = 'white';
  ctx.beginPath();
  ctx.arc(W/2-150, H/2-160, 30, 0, 2*Math.PI);
  ctx.fill();
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2-150, H/2-160, 10, 0, 2*Math.PI);
  ctx.fill();
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(W/2-150, H/2-150);
  ctx.lineTo(W/2-140, H/2-170);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2-150, H/2-150);
  ctx.lineTo(W/2-160, H/2-170);
  ctx.stroke();

  // animate the thought bubble
  ctx.save();
  ctx.translate(W/2-150, H/2-160);
  ctx.rotate(Math.sin(t));
  ctx.beginPath();
  ctx.moveTo(0, -20);
  ctx.lineTo(-10, -30);
  ctx.lineTo(10, -30);
  ctx.closePath();
  ctx.fillStyle = 'yellow';
  ctx.fill();
  ctx.restore();

  ctx.restore();
}
